class Solution { public int countPalindromes(String s){final long mod=1_000_000_007L;long[] leftSingle=new long[10],rightSingle=new long[10];long[][] leftPair=new long[10][10],rightPair=new long[10][10];for(char character:s.toCharArray()){int digit=character-'0';for(int first=0;first<10;first++)rightPair[first][digit]+=rightSingle[first];rightSingle[digit]++;}long answer=0;for(char character:s.toCharArray()){int digit=character-'0';rightSingle[digit]--;for(int second=0;second<10;second++)rightPair[digit][second]-=rightSingle[second];for(int first=0;first<10;first++)for(int second=0;second<10;second++)answer=(answer+leftPair[first][second]*rightPair[second][first])%mod;for(int first=0;first<10;first++)leftPair[first][digit]+=leftSingle[first];leftSingle[digit]++;}return (int)answer;} }
